#!/usr/bin/env python3
"""Rules that 5e.tools lists and the Library lacked (actions, senses, status rules, optional rules). Own wording.
Writes src/data/q13-rule-gaps.js (adds rows to window.QREFS.rule).   python3 tools/q/rule_gaps.py"""
import json
ROWS = [
 ("Cast a Spell", "phb14", "Rule • Action (2014)", [["Time", "Varies"]], ["The casting time on the spell decides what casting costs you. Most spells take 1 action, but some take a Bonus Action, a Reaction, or minutes or hours. Casting uses your action only when the spell says so."]),
 ("Use an Object", "phb14", "Rule • Action (2014)", [["Time", "Action"]], ["You usually handle an object as part of another action, such as drawing a sword while you attack. When an object needs your whole action, or you want to handle several objects in one turn, you take the Use an Object action."]),
 ("Two-Weapon Fighting", "core", "Rule • Action", [["Time", "Bonus Action"]], ["After you take the Attack action and attack with a Light weapon, you can make one extra attack with a Bonus Action later in the same turn. The extra attack must use a different Light weapon. Leave your ability modifier out of its damage unless the modifier is negative."]),
 ("Blindsight", "core", "Rule • Sense", [["Kind", "Sense"]], ["Within its range, you perceive your surroundings without sight. You see anything that is not behind Cover, even while Blinded or in Darkness, and you see Invisible creatures."]),
 ("Tremorsense", "core", "Rule • Sense", [["Kind", "Sense"]], ["Within its range, you pinpoint creatures and moving objects when both of you touch the same surface or liquid. It misses anything in the air and does not count as sight."]),
 ("Truesight", "core", "Rule • Sense", [["Kind", "Sense"]], ["Within its range, your vision cuts through several effects. **Darkness.** You see in normal and magical Darkness. **Invisibility.** You see Invisible creatures and objects. **Illusions.** Visual illusions look transparent, and you pass saving throws against them automatically. **Transformations.** You see the true form of anything changed by magic. **Ethereal Plane.** You see into it."]),
 ("Feats (optional rule)", "phb14", "Rule • Optional (2014)", [["Kind", "Optional"]], ["When your class gives you Ability Score Improvement, you can take a feat instead. You can take each feat once, unless it says otherwise. You need to meet its prerequisite, and you cannot use the feat while you lack it."]),
 ("Firearms", "dmg14", "Rule • Optional (2014)", [["Kind", "Optional"]], ["For campaigns with gunpowder, modern, or futuristic weapons. The DM decides whether characters know how to use them, and in most worlds they do not. Training in downtime can teach it. The Firearms table gives examples from each era."]),
 ("Inspiration", "phb14", "Rule • Optional (2014)", [["Kind", "Optional"], ["Limit", "One at a time"]], ["The DM rewards you for playing true to your traits, ideals, bonds, and flaws. Spend it to gain Advantage on one ability check, attack roll, or saving throw. You can hold only one. DMs hand it out to encourage roleplay and bold choices, so everyone enjoys the game more."]),
 ("Sleep", "xge", "Rule • Optional", [["Kind", "Optional"]], ["A creature sleeping naturally has the Unconscious condition. Damage wakes it, and so does someone using an action to shake or slap it, or a loud noise such as yelling or thunder. Whispers do not wake it unless its passive Wisdom (Perception) is 20 or higher and they are within 10 feet. Normal speech wakes it in a quiet place if its passive Wisdom (Perception) is 15 or higher. **Armor.** Light armor causes no problem. After a long rest in Medium or Heavy armor, you regain only a quarter of your spent Hit Dice (at least one) and your Exhaustion does not go down."]),
 ("Spellcasting (expanded rules)", "xge", "Rule • Optional", [["Kind", "Optional"]], ["Extra spellcasting rules. **Perceiving a cast.** A casting is noticeable only if it uses a verbal, somatic, or material component. Without components, such as Subtle Spell or Innate Spellcasting, it cannot be noticed. **Identifying a spell.** Use a reaction while it is cast, or an action after it takes effect, and make an Intelligence (Arcana) check, DC 15 plus the spell's level. You have Advantage if the spell was cast as a spell of your own class. **Invalid targets.** A spell cast on a target it cannot affect does nothing to that target."]),
]
rows = [{"n": n, "s": s, "sub": sub, "tl": tl, "p": p, "tx": (n + " " + sub + " " + " ".join(p)).lower().replace("**", "")} for n, s, sub, tl, p in ROWS]
open("src/data/q13-rule-gaps.js", "w", encoding="utf-8").write("/* Generated by tools/q/rule_gaps.py. Own wording. Do not edit by hand. */\n(function(){\nvar ROWS=" + json.dumps(rows, ensure_ascii=False) + ';\nwindow.QREFS=window.QREFS||{};window.QREFS["rule"]=(window.QREFS["rule"]||[]).concat(ROWS);\n})();\n')
print(len(rows), "rows")
